#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# Fase 8c -- Corrige el fallo de build en Docker/CI reportado por Raúl.
#
# Causa real: `Order.serviceType` es un campo OPCIONAL en el esquema Prisma
# (ServiceType?), pero mi código de la Fase 8b lo usaba como si siempre
# tuviera valor al calcular la clave de agrupación en /routes/auto-plan. En
# este sandbox el cliente Prisma generado está incompleto y no marcaba el
# error; en el entorno real de Raúl, con el cliente completo, `tsc` sí lo
# detectó correctamente y bloqueó el build. Se corrige añadiendo un valor por
# defecto ("paleteria", el mismo que ya usa el alta manual de ruta) cuando
# ni se ha forzado un servicio ni el pedido tiene uno clasificado.
#
# De paso se corrige un problema del mismo origen en el frontend
# (PlanificacionTab.tsx), donde el tipo de "serviceType" no reflejaba que
# puede venir nulo desde el backend -- no rompía el build local, pero era el
# mismo agujero de tipado y ya está expuesto en la interfaz visible (chip
# "Sin clasificar").
#
# Solo toca estos dos ficheros, ambos ya entregados en fases anteriores.
# No se añade ni se quita ninguna funcionalidad -- es una corrección de tipos.
# ============================================================================

TARGET_DIR="${1:-.}"
cd "$TARGET_DIR"

echo "Aplicando Fase 8c (corrección build) sobre: $(pwd)"
echo

FILES_APPLIED=(
  "backend/src/modules/routes/routes.routes.ts"
  "frontend/src/pages/planner/PlanificacionTab.tsx"
)

echo "-> backend/src/modules/routes/routes.routes.ts"
mkdir -p "$(dirname "backend/src/modules/routes/routes.routes.ts")"
base64 -d > "backend/src/modules/routes/routes.routes.ts" <<'B64EOF_backend_src_modules_routes_routes_routes_ts'

B64EOF_backend_src_modules_routes_routes_routes_ts

echo "-> frontend/src/pages/planner/PlanificacionTab.tsx"
mkdir -p "$(dirname "frontend/src/pages/planner/PlanificacionTab.tsx")"
base64 -d > "frontend/src/pages/planner/PlanificacionTab.tsx" <<'B64EOF_frontend_src_pages_planner_PlanificacionTab_tsx'

B64EOF_frontend_src_pages_planner_PlanificacionTab_tsx

echo
echo "Fase 8c aplicada correctamente."
echo "Ficheros actualizados:"
for f in "${FILES_APPLIED[@]}"; do
  echo "  - $f"
done
